function KMHashTable(t){this.values={},this.numberOfValues=0,this.size=t}KMHashTable.prototype.add=function(t,s){var e=this.calculateHash(t);this.values.hasOwnProperty(e)||(this.values[e]={}),this.values[e].hasOwnProperty(t)||this.numberOfValues++,this.values[e][t]=s},KMHashTable.prototype.remove=function(t){var s=this.calculateHash(t);this.values.hasOwnProperty(s)&&this.values[s].hasOwnProperty(t)&&(delete this.values[s][t],this.numberOfValues--)},KMHashTable.prototype.calculateHash=function(t){return t.toString().length%this.size},KMHashTable.prototype.search=function(t){var s=this.calculateHash(t);return this.values.hasOwnProperty(s)&&this.values[s].hasOwnProperty(t)?this.values[s][t]:null},KMHashTable.prototype.length=function(){return this.numberOfValues},KMHashTable.prototype.print=function(){var t="";for(var s in this.values)for(var e in this.values[s])t+=this.values[s][e]+" ";console.log(t.trim())};
